/// The snapshot-free half of `AsyncApi`. `batchRequests` is absent for the reason `AsyncApi`
/// omits it: the mailbox is already the batcher.
[<Extension>]
type AsyncSessionlessExtensions =

    [<Extension>]
    static member initialize(this: SessionlessApi<TscMailbox>) =
        AsyncApi.initialize this.Transport

    [<Extension>]
    static member updateSnapshot(this: SessionlessApi<TscMailbox>, [<Struct>] ?openProjects: DocumentIdentifier[], [<Struct>] ?closeProjects: DocumentIdentifier[], [<Struct>] ?fileChanges: APIFileChanges, [<Struct>] ?openFiles: DocumentIdentifier[], [<Struct>] ?closeFiles: DocumentIdentifier[]) =
        let parameters: UpdateSnapshotParams =
            { OpenProjects = openProjects
              CloseProjects = closeProjects
              FileChanges = fileChanges
              OpenFiles = openFiles
              CloseFiles = closeFiles }

        AsyncApi.updateSnapshot this.Transport parameters

    [<Extension>]
    static member createProgram(this: SessionlessApi<TscMailbox>, createProgramOptions: CreateProgramOptions, [<Struct>] ?rootFiles: DocumentIdentifier[], [<Struct>] ?oldProgram: CreateProgramOldProgramParams, [<Struct>] ?fileChanges: APIFileChanges) =
        let parameters: CreateProgramParams =
            { CreateProgramOptions = createProgramOptions
              RootFiles = rootFiles
              OldProgram = oldProgram
              FileChanges = fileChanges }

        AsyncApi.createProgram this.Transport parameters

    [<Extension>]
    static member parseCommandLine(this: SessionlessApi<TscMailbox>, [<Struct>] ?commandLine: string[]) =
        let parameters: ParseCommandLineParams =
            { CommandLine = commandLine }

        AsyncApi.parseCommandLine this.Transport parameters

    [<Extension>]
    static member readConfigFile(this: SessionlessApi<TscMailbox>, file: DocumentIdentifier) =
