/// Ways to get a session. The snapshot and project always come from a response that already
/// pairs them, so the overloads below take those responses rather than leaving a caller to
/// unpack the pair and risk crossing a snapshot with another snapshot's project.
[<Extension>]
type SessionConstructors =

    /// A session on `channel` over a snapshot and project named directly.
    [<Extension>]
    static member Session(this: TscChannel, snapshot: int, project: string) =
        { Transport = this; Snapshot = snapshot; Project = project }

    /// A session on what `createProgram` handed back. Raises when the response carries no
    /// project, which is the compiler saying the root files resolved to no program at all.
    [<Extension>]
    static member Session(this: TscChannel, program: CreateProgramResponse) =
        match program.Project with
        | ValueSome project -> { Transport = this; Snapshot = program.Snapshot; Project = project.Id }
        | ValueNone -> failwith "createProgram returned no project, so there is nothing to open a session on"

    /// A session on one project of a snapshot, named by id. A snapshot can hold several, so the
    /// project is not inferred.
    [<Extension>]
    static member Session(this: TscChannel, snapshot: UpdateSnapshotResponse, project: string) =
        { Transport = this; Snapshot = snapshot.Snapshot; Project = project }

    /// A session on a snapshot's only project. Raises when the snapshot holds none or several,
    /// so a caller opening one project never has to index into the array.
    [<Extension>]
    static member Session(this: TscChannel, snapshot: UpdateSnapshotResponse) =
        match snapshot.Projects with
        | [| project |] -> { Transport = this; Snapshot = snapshot.Snapshot; Project = project.Id }
        | projects ->
            failwithf "the snapshot holds %d projects, so name the one to open a session on" projects.Length

    /// A session on `mailbox` over a snapshot and project named directly.
    [<Extension>]
    static member Session(this: TscMailbox, snapshot: int, project: string) =
        { Transport = this; Snapshot = snapshot; Project = project }

    /// A session on what `createProgram` handed back. Raises when the response carries no
    /// project, which is the compiler saying the root files resolved to no program at all.
    [<Extension>]
    static member Session(this: TscMailbox, program: CreateProgramResponse) =
        match program.Project with
        | ValueSome project -> { Transport = this; Snapshot = program.Snapshot; Project = project.Id }
        | ValueNone -> failwith "createProgram returned no project, so there is nothing to open a session on"

    /// A session on one project of a snapshot, named by id. A snapshot can hold several, so the
    /// project is not inferred.
    [<Extension>]
    static member Session(this: TscMailbox, snapshot: UpdateSnapshotResponse, project: string) =
        { Transport = this; Snapshot = snapshot.Snapshot; Project = project }

    /// A session on a snapshot's only project. Raises when the snapshot holds none or several,
    /// so a caller opening one project never has to index into the array.
    [<Extension>]
    static member Session(this: TscMailbox, snapshot: UpdateSnapshotResponse) =
        match snapshot.Projects with
        | [| project |] -> { Transport = this; Snapshot = snapshot.Snapshot; Project = project.Id }
        | projects ->
            failwithf "the snapshot holds %d projects, so name the one to open a session on" projects.Length

